  <script>
    // Accordion toggle function
    function toggleAccordion(id) {
      const content = document.getElementById(id);
      const btn = document.getElementById('btn-' + id);
      const expanded = btn.getAttribute('aria-expanded') === 'true';

      // Close all
      document.querySelectorAll('.accordion-button').forEach(button => {
        button.setAttribute('aria-expanded', 'false');
        const cId = button.getAttribute('aria-controls');
        document.getElementById(cId).classList.add('hidden');
      });

      if (!expanded) {
        btn.setAttribute('aria-expanded', 'true');
        content.classList.remove('hidden');
        btn.focus();
      }
    }

    // Initialize first accordion open
    document.addEventListener('DOMContentLoaded', () => {
      toggleAccordion('collapse1');
    });

    // Dark mode toggle
    const darkToggle = document.getElementById('darkToggle');
    const html = document.documentElement;

    function setDarkMode(on) {
      if (on) {
        html.classList.add('dark');
        darkToggle.innerHTML = '<i class="fas fa-sun" aria-hidden="true"></i>';
        darkToggle.setAttribute('aria-label', 'Világos világítás');
        darkToggle.title = 'Világos világítás';
        darkToggle.setAttribute('aria-pressed', 'true');
        document.body.style.backgroundColor = '#1f2937';
        document.body.style.color = '#f9fafb';
      } else {
        html.classList.remove('dark');
        darkToggle.innerHTML = '<i class="fas fa-moon-stars" aria-hidden="true"></i>';
        darkToggle.setAttribute('aria-label', 'Sötét világítás');
        darkToggle.title = 'Sötét világítás';
        darkToggle.setAttribute('aria-pressed', 'false');
        document.body.style.backgroundColor = '#ffffff';
        document.body.style.color = '#1f2937';
      }
      localStorage.setItem('darkMode', on ? '1' : '0');
    }

    darkToggle.addEventListener('click', () => {
      setDarkMode(!html.classList.contains('dark'));
    });

    // Load dark mode preference
    if (localStorage.getItem('darkMode') === '1') {
      setDarkMode(true);
    }
  </script>
